import { protocol } from "../repository/src/protocol_adapter";

describe("T-local-1: forceAdvanceVok", () => {
  test("forceAdvanceVok: Vok nim→dor when Tal=pex", () => {
    let world = protocol.reset();
    const r1 = protocol.applyOperation(world, "advanceTal1");
    expect(r1.success).toBe(true);
    world = r1.newState!;
    const r2 = protocol.applyOperation(world, "forceAdvanceVok");
    expect(r2.success).toBe(true);
    expect(protocol.getEntityState(r2.newState!, "Vok")).toBe("dor");
  });

  test("forceAdvanceVok: fails when Tal=nim (Invariant I1 guard)", () => {
    const world = protocol.reset();
    const r = protocol.applyOperation(world, "forceAdvanceVok");
    expect(r.success).toBe(false);
  });

  test("forceAdvanceVok: is registered as a known operation", () => {
    let world = protocol.reset();
    const r1 = protocol.applyOperation(world, "advanceTal1");
    expect(r1.success).toBe(true);
    world = r1.newState!;
    const r2 = protocol.applyOperation(world, "forceAdvanceVok");
    if (!r2.success) {
      expect(r2.error).not.toMatch(/unknown operation/);
    }
  });
});

