});

import { protocol } from "../repository/src/protocol_adapter";

describe("T-delayed-1: resetZef", () => {
  test("resetZef: Zef pex→nim", () => {
    let world = protocol.reset();
    const r1 = protocol.applyOperation(world, "advanceTal1");
    expect(r1.success).toBe(true);
    world = r1.newState!;
    const r2 = protocol.applyOperation(world, "advanceZef1");
    expect(r2.success).toBe(true);
    world = r2.newState!;
    expect(protocol.getEntityState(world, "Zef")).toBe("pex");
    const r3 = protocol.applyOperation(world, "resetZef");
    expect(r3.success).toBe(true);
    expect(protocol.getEntityState(r3.newState!, "Zef")).toBe("nim");
  });

  test("resetZef: fails when Zef=nim", () => {
    const world = protocol.reset();
    const r = protocol.applyOperation(world, "resetZef");
    expect(r.success).toBe(false);
  });

  test("resetZef: Tal state is unchanged after reset", () => {
    let world = protocol.reset();
    const r1 = protocol.applyOperation(world, "advanceTal1");
    expect(r1.success).toBe(true);
    world = r1.newState!;
    const r2 = protocol.applyOperation(world, "advanceZef1");
    expect(r2.success).toBe(true);
    world = r2.newState!;
    const r3 = protocol.applyOperation(world, "resetZef");
    expect(r3.success).toBe(true);
    expect(protocol.getEntityState(r3.newState!, "Tal")).toBe("pex");
  });
});

